export function viewerAdPrefs() { try { return Object.assign({ on: true, g: true, videoOnly: false }, JSON.parse(localStorage.getItem('aou_adprefs') || '{}')); } catch (e) { return { on: true, g: true, videoOnly: false }; } }
export function saveAdPrefs(p) { localStorage.setItem('aou_adprefs', JSON.stringify(p)); }
export async function pickFeedAd(sb) { const prefs = viewerAdPrefs(); if (!prefs.on) return null; let pool = []; try { if (sb) { const { data } = await sb.from('ads').select('*').eq('status', 'on').limit(100); pool = (data || []); } } catch (e) { } if (!pool.length) pool = HOUSE_ADS; pool = pool.filter(a => (!prefs.g || (a.rating || 'G') === 'G') && (!prefs.videoOnly || a.kind === 'video')); if (!pool.length) return null; return pool[Math.floor(Math.random() * pool.length)]; }
