    if (tab === 'pages') { const MINE = [['eye-to-ad-media', 'Eye To Ad Media', 'SEO, AIO, GEO and websites. Denver HQ, growing businesses worldwide.', '1-800-481-8638', 'https://eyetoad.com/', 'Denver, CO'], ['search-converts', 'Search Converts', 'Full-service marketing: PPC, social, press, websites.', '1-800-481-8638', 'https://searchconverts.com/', 'Denver, CO'], ['aging-safely-baths', 'Aging Safely Baths', 'Walk-in tubs and accessible showers since 2012.', '888-779-2284', 'https://www.agingsafelybaths.com/', 'Denver, CO'], ['showers4less', 'Showers4Less', '371 showers, pans and doors. Made-in-USA options.', '888-779-2284', 'https://showers4less.com/', 'Denver, CO'], ['elevation-health', 'Elevation Health', 'GLP-1 weight-loss care.', '', 'https://loseweightonglp1.com/', 'Colorado'], ['bighorn-painting', 'Bighorn Painting', 'Interior and exterior painting, Denver metro.', '', 'https://denverpaintcontractors.com/', 'Arvada, CO'], ['painting-brighton', 'Painting Brighton', 'House painting in Brighton and the north metro.', '', 'https://paintingbrighton.com/', 'Brighton, CO'], ['raised-in-a-barn', 'Raised In a Barn Furniture', 'Handcrafted barnwood furniture, free shipping.', '(970) 518-2883', 'https://rusticbarnwoodfurniture.com/', 'Colorado'], ['bear-creek-auto-glass', 'Bear Creek Auto Glass', 'Windshields and auto glass, Littleton.', '', 'https://bearcreekautoglass.com/', 'Littleton, CO'], ['my-sales-help', 'My Sales Help', 'Sales training that actually gets used.', '', 'https://mysaleshelp.com/', 'Denver, CO'], ['world-vr-mall', 'World VR Mall', 'The 3D mall you can walk through.', '1-800-481-8638', 'https://worldvrmall.com/', 'Everywhere']]; const owner = me && /zach@eyetoad\.com|zachwennstedt@gmail\.com/i.test(me.email || ''); let pages = []; try { if (sb && me) { const { data } = await sb.from('pages').select('*').eq('owner_id', me.id); pages = data || []; } } catch (e) { } D.innerHTML = `<div class="card"><h2>💼 My business pages</h2><p class="muted">A page runs from your personal profile. Post as the business, take messages, link your ads to it, show up in the directory and the 3D mall.</p>${pages.length ? pages.map(p => `<div class="adrow"><div class="pv">${p.logo ? `<img src="${esc(p.logo)}" alt="">` : '💼'}</div><div style="flex:1"><b>${esc(p.name)}</b><br><small class="muted">/?page=${esc(p.slug)}</small></div><a class="btn sm" href="/?page=${esc(p.slug)}">Open</a></div>`).join('') : '<p class="muted">No pages yet.</p>'}<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px"><a class="btn p" href="/?v=brand">＋ Create a page</a>${owner ? '<button class="btn g" id="mk-net">⚡ Set up the Eye To Ad Media network pages (11)</button>' : ''}</div></div>`; const mk = $('#mk-net', D); if (mk) mk.onclick = async () => { let n = 0; for (const [slug, name, tagline, phone, website, loc] of MINE) { if (pages.some(p => p.slug === slug)) continue; const { error } = await sb.from('pages').insert({ owner_id: me.id, slug, name, tagline, phone, website, location: loc, about: tagline }); if (!error) n++; } toast('✅ ' + n + ' pages created'); render(); }; return; }
